(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["gd"] = {"ui":{"skip":"Leum gu susbaint","back":"← Air ais gu AI-gile","lang.button":"Cànan: {name}","lang.dialog":"Tagh cànan","lang.search":"Lorg cànan","lang.none":"Chan eil cànan a’ freagairt","lang.notYet":"Chan eil {name} air eadar-theangachadh fhathast","theme.aria":"Atharraich eadar an dà chuid dhen ùrlar shoilleir is dhorcha","theme.toLight":"Atharraich gu ùrlar soilleir","theme.toDark":"Atharraich gu ùrlar dorcha","index.title":"AI-gile: an sgioba AI agad, air aon bhòrd","index.description":"Is e bòrd kanban a th’ ann an AI-gile airson sgiobaidhean còdaidh AI. Bidh iad ag obair fhad ’s a tha thu nad chadal; gheibh thu aon chrann beag de rudan airson co-dhùnadh, deuchainn agus gabhail ris.","hero.logoAlt":"Ìomhaigheag bhòrd AI-gile","hero.h1.html":"An sgioba AI agad, air aon&nbsp;bhòrd.","hero.alpha":"🐣 Ro-alpha dùinte","hero.alphaTitle":"Tràth agus neo-chrìochnaichte: tapadh leibh airson feuchainn air!","hero.lede":"Bidh iad a’ togail fhad ’s a tha thu nad chadal. Tha thu a’ dùsgadh gu aon chrann beag: beagan cheistean, beagan rudan airson deuchainn, daoimean purpaidh no dhà. Briog, gabh ris, air ais chun a’ chofaidh agad.","dl.windows":"Aplacaid Windows","dl.browser":"Ruith e sa bhrabhsair agad","dl.soon":"Dhan ath-ghoirid","dl.notify":"🔔 Innis dhomh nuair a dh’fhosglas e","dl.notifySmall":"Alpha no beta","hero.secondary":"Agile, ach chan fheum an sgioba cofaidh seasamh a-chaoidh. (Bidh stand-ups aca co-dhiù.)","pitch.h2":"AI-gile ann an uiread de dh’fhaclan ’s as toil leat","pitch.lede":"Tagh fad, o aon fhacal gu 144. Tha gach fad na thuairisgeul fhèin, sgrìobhte airson a mheud. Slaod an sleamhnachan no cleachd na saighdean.","pitch.rangeLabel":"Fad ann am faclan","pitch.dice":"🎲 tionndadh eile","pitch.words.one":"{n} fhacal","pitch.words.other":"{n} facal","pitch.letters.one":"{n} litir","pitch.letters.other":"{n} litir","pitch.chars.one":"{n} charactar","pitch.chars.other":"{n} caractar","count.line.html.one":"{n} chairt air a’ bhòrd an-dràsta","count.line.html.other":"{n} cairt air a’ bhòrd an-dràsta","features.aria":"Dè a nì e","f.pile.h":"Aon chrann dhutsa","f.pile.html":"Tha <b>Dhutsa</b> a’ cumail a h-uile rud a tha a’ feitheamh ort, thar gach pròiseact: ceistean, rudan airson deuchainn, obraichean nach urrainn ach dhut fhèin a dhèanamh. Tha do chiudha ag innse dè th’ ann an ath-ghnothach agus dè cho fada ’s a bheir e.","f.sleep.h":"Sgiobaidhean a bhios ag obair fhad ’s a tha thu nad chadal","f.sleep.p":"Tha stiùiriche agus sgioba de dh’àidseantan AI aig gach pròiseact. Cuir beachd air cairt agus dùisgidh an sgioba, nì iad an obair agus bheir iad air ais i le ceumannan as urrainn do dhuine claoidhte a leantainn.","f.tester.h":"Bidh deuchainniche AI a’ sgrùdadh an toiseach","f.tester.p":"Mus ruig dad thu, leanaidh deuchainniche na ceumannan ann an lethbhreac dhen aplacaid agus seallaidh e na chunnaic e, le glacadh-sgrìn. Dèan sùil air an fheadhainn a shoirbhich agus gabh riutha le aon bhriogadh.","f.proof.h":"Dearbhadh, chan e geallaidhean","f.proof.p":"Seallaidh gach lìbhrigeadh na dh’atharraich: na faidhlichean, an diff, na glacaidhean-sgrìn. Chan fheum thu gach aplacaid fhosgladh airson faicinn a bheil e deiseil.","f.chat.h":"Dèan cabadaich le do stiùirichean","f.chat.p":"Rèile mar Discord: aon ìomhaigheag airson gach pròiseact, daoimeanan purpaidh airson na tha gad iarraidh. Cuir teachdaireachd gu stiùiriche le beachd; nì iad cairtean agus plana dheth, le putan ✅ Go.","f.tidy.h":"Cumaidh e fhèin òrdail","f.tidy.p":"Thèid cairtean co-cheangailte a phasgadh nan aon, thèid tiotalan measgaichte a cheartachadh, agus cumaidh sgrùdadh tòcan an còd caol. Nas lugha ri ghluasad eatorra, nas lugha ri smaoineachadh.","f.private.h":"Leatsa, air a’ choimpiutair agad","f.private.li1":"Ruithidh am bòrd air an inneal agad fhèin agus freagraidh e dhutsa a-mhàin.","f.private.li2":"Tha DMan prìobhaideach eadar daoine crioptaichte o cheann gu ceann.","f.private.li3":"Chan eil cunntasan, luchd-leantainn no briosgaidean ann.","f.lang.h":"Nad chànan fhèin","f.lang.p":"Còrr is 120 cànan, bhon Duitsis, a’ Chuimris agus Seapanais gu spùinneadair, Yoda agus Klingon, le leum luath air ais gu Beurla airson faclan an luchd-leasachaidh.","tl.aria":"Loidhne-ama on chiad chòmhradh chun a’ mhapa-rathaid","tl.h2":"On chiad chabadaich gu na tha romhainn","tl.lede":"Cinn-latha agus amannan fìor, san roinn-tìde agad fhèin. Às dèidh an-diugh is e am plana a th’ ann, gun cheann-latha a ghealltainn.","tl.today":"An-diugh","tl.planned":"san dealbh","tl.cards.one":"{n} chairt","tl.cards.other":"{n} cairt","join.h2":"Thig an sàs","join.lede":"Tha AI-gile ga thogail le aon duine beag agus mòran àidseantan foighidneach. Tha e prìobhaideach an-dràsta, ann an alpha dùinte le caraidean. A bheil thu ag iarraidh deuchainn nuair a dh’fhosglas e?","join.btn":"Clàraich ùidh","join.small":"Cuiridh sinn post-d thugad, agus chan eil a bharrachd","footer.tag":"AI-gile. Gun luchd-leantainn, gun bhriosgaidean, gun chofaidh stand-up.","footer.licence":"Cead gnìomhachais","footer.status":"Inbhe","form.sending":"Ga chur…","form.failed":"Cha do dh’obraich sin: feuch a-rithist uaireigin eile.","form.offline":"Cha b’ urrainn ruighinn air AI-gile: feuch a-rithist uaireigin eile.","interest.title":"AI-gile: innis dhomh nuair a dh’fhosglas an alpha","interest.description":"Fàg do phost-d airson cluinntinn cuin a dh’fhosglas alpha no beta dùinte AI-gile.","interest.h1":"🔔 Innis dhomh nuair a dh’fhosglas e","interest.lede":"Tha AI-gile ann am ro-alpha dùinte. Fàg do phost-d agus sgrìobhaidh sinn aon turas, nuair a bhios àite dhut.","interest.email":"Do phost-d","interest.which":"Dè an deuchainn?","interest.alpha":"Alpha dùinte: tràth, garbh, tòrr atharraichean","interest.beta":"Beta: nas seasmhaiche, nas fhaide air adhart","interest.both":"An dàrna fear, ge brith dè thig an toiseach","interest.submit":"Cuir air an liosta mi","interest.thanks":"Tapadh leat! Tha thu air an liosta.","interest.kept":"Cha tèid ach do phost-d agus an deuchainn a thagh thu a chumail, airson an liosta seo a-mhàin. Gun naidheachdan-puist, gun luchd-leantainn.","licence.title":"AI-gile: cead gnìomhachais","licence.description":"A’ cleachdadh AI-gile san gnìomhachas agad? Cuir iarrtas a-steach airson cead gnìomhachais an-asgaidh.","licence.h1":"📜 Cead gnìomhachais","licence.lede":"A’ cleachdadh AI-gile san obair? Innis dhuinn cò thu agus dè a nì thu. Ma nì e deagh, tha an cead an-asgaidh.","licence.company":"Companaidh","licence.website":"Làrach-lìn","licence.what":"Dè a nì thu","licence.how":"Mar a chuidicheas e an saoghal","licence.email":"Post-d","licence.submit":"Cuir a-steach","licence.thanks":"Tapadh leat! Freagraidh sinn air a’ phost-d.","status.title":"Inbhe AI-gile","status.h1":"Inbhe AI-gile","status.quiet":"Sàmhach gu leòr","status.checking":"A’ sgrùdadh…","status.offline":"Chan urrainn ruighinn air seirbheis na h-inbhe an-dràsta (a’ feuchainn a-rithist)","status.updated":"air ùrachadh {ago}","status.justNow":"o chionn mionaid","status.min":"{n} mion. air ais","status.hours":"{n} u. air ais","status.days":"{n} l. air ais","pitch.words.two":"{n} fhacal","pitch.words.few":"{n} faclan","pitch.letters.two":"{n} litir","pitch.letters.few":"{n} litrichean","pitch.chars.two":"{n} charactar","pitch.chars.few":"{n} caractaran","count.line.html.two":"{n} chairt air a’ bhòrd an-dràsta","count.line.html.few":"{n} cairtean air a’ bhòrd an-dràsta","tl.cards.two":"{n} chairt","tl.cards.few":"{n} cairtean","live.h2":"Seall air ga thogail, beò","live.caption":"Tha gach cairt falaichte: chì thu cumadh na h-obrach, chan e na faclan.","live.watching.one":"beò: {n} a’ coimhead","live.watching.other":"beò: {n} a’ coimhead","live.offline":"Tha am bòrd beò a’ gabhail anail. Till a dh’aithghearr.","live.cols":"Backlog|Ri dhèanamh|Ga dhèanamh|An sgioba a’ sgrùdadh|Dhutsa ri test|Dhan sgioba|Deiseil","live.last.now":"Chaidh a’ chairt mu dheireadh a ghluasad an-dràsta fhèin","live.last.min.one":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} mhionaid","live.last.min.other":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} mionaidean","live.last.hour.one":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} uair a thìde","live.last.hour.other":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} uairean a thìde","live.last.day.one":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} latha","live.last.day.other":"Chaidh a’ chairt mu dheireadh a ghluasad o {n} làithean"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robotan.","Tiomnaichte."]},{"n":2,"texts":["Kanban robotach.","Àidseantan, òrdail.","Beachdan, togte."]},{"n":3,"texts":["Kanban airson robotan.","Bidh beachdan nan gleusan.","Kanban àidseant, saor."]},{"n":5,"texts":["Bòrd kanban le àidseantan ga ruith.","Sgrìobh cairtean. Togaidh àidseantan.","Saor, ionadail, deuchainnichte, rudeigin gòrach."]},{"n":8,"texts":["Bòrd kanban saor far am bi àidseantan AI ag obair.","Sgrìobh beachd. Togaidh àidseantan e. Gabhaidh tu ris.","Agile airson aon duine agus mòran robotan foighidneach."]},{"n":13,"texts":["Bòrd kanban air a’ choimpiutair agad far an togar na cairtean le àidseantan AI.","Sgrìobh beachd air a’ bhòrd. Togaidh sgioba de dh’àidseantan e agus sgrùdaidh deuchainniche e.","Saor, gun chunntasan, gun luchd-leantainn: bòrd, beagan robotan, agus thusa os an cionn."]},{"n":21,"texts":["AI-gile: bòrd kanban airson obrachadh le àidseantan còdaidh AI. Togaidh iadsan na cairtean; nì thusa deuchainn orra is gabhaidh tu riutha.","Gheibh gach pròiseact stiùiriche agus sgioba de dh’àidseantan AI. Cuir beachd air cairt sam bith agus tòisichidh an sgioba air obair.","Bòrd saor pearsanta a ruitheas air do choimpiutair fhèin. Is e robotan an luchd-obrach. Is e thusa an tè no am fear a their ‘tha’."]},{"n":34,"texts":["Cuiridh tu beachdan air bòrd. Tionndaidhidh sgioba de dh’àidseantan AI iad gu gleusan obrach, nì iad deuchainn orra, agus bheir iad air ais thugad iad le ceumannan airson feuchainn. Chan eil dad deiseil gus an can thusa e.","Tha AI-gile na bhòrd kanban dachaigh a thog Rich le tòrr cuideachaidh bho na h-àidseantan a tha e a-nis a’ stiùireadh. Tha e an-asgaidh, a’ ruith air do choimpiutair, agus air a cho-roinn le caraidean, chan e reic.","Smaoinich air bòrd kanban àbhaisteach, le colbhan o Backlog gu Deiseil, ach gu bheil na cairtean air an togail le àidseantan AI. Bheir iad aithris air adhartas, faighnichidh iad nuair a tha iad steigte, agus feitheamh iad ri do làmh-suas an-còmhnaidh."]},{"n":55,"texts":["Is e bòrd kanban a th’ ann an AI-gile far a bheil an sgioba air a dèanamh de dh’àidseantan AI. Tha stiùiriche aig gach pròiseact a dhealbhas an obair agus cuidichean a thogas i. Nuair a bhios gleus deiseil, feuchaidh deuchainniche AI e agus gabhaidh e glacadh-sgrìn, agus an uairsin ruigidh e do chrann. Gabh ris, no cuir beachd agus nì iad ath-obair air.","Thòisich e mar dhòigh aig aon neach air sùil a chumail air tòrr seiseanan còdaidh AI aig an aon àm, agus dh’fhàs e na bhòrd ceart. Ruithidh e air d’ inneal, chan eil cunntas a dhìth, agus chan eil luchd-leantainn ann. Tha e an-asgaidh. Tha e cuideachd neo-chrìochnaichte, mar sin cuir roimhe cliathaichean garbha agus iongnadh an dràsta ’s a-rithist.","Seo an dreach onarach. Feumaidh tu fhathast na beachdan a bhith agad, agus feumaidh tu fhathast na toraidhean a sgrùdadh. Is e na nì AI-gile gach rud eatorra: cumaidh e na cairtean an òrdugh, dùisgidh e an àidseant cheart nuair a chuireas tu beachd, seallaidh e dè dìreach a dh’atharraich, agus cumaidh e a h-uile rud nad aon chrann ghoirid."]},{"n":89,"texts":["Is e bòrd kanban saor a th’ ann an AI-gile a ruitheas tu air do choimpiutair fhèin. An àite dhaoine, tha sgioba de dh’àidseantan AI aig gach pròiseact: stiùiriche a thionndaidheas do bheachdan gu cairtean agus plana, agus cuidichean a thogas na cairtean a-rèir prìomhachais. Nuair a tha rudeigin togte, leanaidh deuchainniche AI na ceumannan deuchainn agus seallaidh e dhut na chunnaic e. An uairsin feitheamh e ann an aon chrann air a bheil Dhutsa. Gabhaidh tu ris, no cuiridh tu beachd agus bheir an sgioba oidhirp eile. Chan ruig dad Deiseil às d’ aonais.","Beagan ghleusan nach biodh dùil agad riutha. Cumaidh faire na h-oidhche an colbh Ri dhèanamh làn fhad ’s a tha thu nad chadal, a’ taghadh chairtean nach fheum freagairt bhuat. Seallaidh cunntair thòcan dhut dè an uiread a chleachd na h-àidseantan an-diugh agus an t-seachdain seo, agus cuiridh No Token Mode stad air an caitheamh. Faodaidh tu teachdaireachdan a chur gu caraidean, agus tha teachdaireachdan prìobhaideach crioptaichte o cheann gu ceann. Bruidhnidh am bòrd mu 120 cànan, a’ gabhail a-steach Duitsis, Flemis, spùinneadair agus Klingon. Chan eil bonn sam bith a’ cosg, agus chan eil duine feuchainn ri a reic riut.","Is e pròiseact beag pearsanta a th’ ann an AI-gile, chan e companaidh. Bha Rich ag iarraidh coimhead às dèidh grunn phròiseactan còdaidh AI gun a h-uile aplacaid fhosgladh airson sùil a thoirt orra, agus mar sin thog e fhèin agus na h-àidseantan bòrd dhan sin, agus an uairsin chleachd iad am bòrd gus a’ chòrr dheth a thogail. Tha e ann am ro-alpha dùinte, is e sin gu bheil e ag obair, sa mhòr-chuid, airson dòrlach de charaidean. Chan eil duilleag phrìsean no plana fàis ann. Ma tha e feumail dhut, faodaidh tu iarraidh feuchainn air nuair a dh’fhosglas e."]},{"n":144,"texts":["Is e bòrd kanban a th’ ann an AI-gile airson aon duine agus tòrr àidseantan AI. Ruithidh e air do choimpiutair fhèin agus tha e gu tur an-asgaidh. Cuiridh tu pròiseactan ris, agus gheibh gach pròiseact stiùiriche agus sgioba bheag. Nì thu cabadaich leis an stiùiriche, rudeigin coltach ri Discord, agus mìnichidh tu beachd; tionndaidhidh an stiùiriche e gu cairtean agus plana, agus an uairsin feitheamh e ort gus Go a bhrùthadh. Obraichidh an sgioba tro na cairtean a-rèir prìomhachais, le loidhne-àithne shìmplidh a chaidh a dhèanamh airson modailean cànain. Mus till dad thugad, leanaidh deuchainniche AI na ceumannan ann an lethbhreac dhen aplacaid agus cuiridh e glacadh-sgrìn ris. Ruigidh obair chrìochnaichte do chrann leis na faidhlichean a dh’atharraich agus an diff. Gabhaidh tu ris, no fàgaidh tu beachd agus dùisgidh an sgioba agus feuchaidh iad a-rithist. Chan urrainn ach dhutsa cairt a ghluasad gu Deiseil.","Latha le AI-gile, mu thimcheall. Feasgar fàgaidh tu beagan bheachdan: tha am putan seo san àite cheàrr, bu chòir an liosta sin a bhith air a rèiteachadh, am faigheadh sinn modh dorcha. Falbhaidh tu dhan leabaidh. Leughaidh na h-àidseantan na beachdan, nì iad na h-atharraichean, nì iad deuchainn orra agus bheir iad air ais thugad iad. Ma thraogas Ri dhèanamh, lìonaidh faire na h-oidhche e às a’ Backlog le cairtean nach fheum freagairt bhuat. Sa mhadainn tha aon chrann ghoirid ann: càraid cheistean agus beagan rudan airson feuchainn, gach fear le ceumannan as urrainn do dhuine cadalach a leantainn agus glacadh-sgrìn dheth ag obair. Briogaidh tu tro, gabhaidh tu ris an fheadhainn mhath agus cuiridh tu air ais a’ chòrr. Seallaidh cunntair thòcan na chaidh a chaitheamh, agus tha No Token Mode ann airson seachdainean caola. An uairsin gheibh thu do bhrath-bhìdh, nach urrainn dha na h-àidseantan cuideachadh leis fhathast.","An toiseach, dè nach eil AI-gile. Chan e tòiseachadh-suas a th’ ann, chan eil e ri reic, agus chan eil duine a’ cruinneachadh d’ dàta. Is e bòrd saor a th’ ann a ruitheas air do choimpiutair, gun chunntasan, gun luchd-leantainn agus gun bhriosgaidean. Is e a th’ ann: aon àite òrdail airson a h-uile pròiseact còdaidh AI fhaicinn aig an aon àm, le sgioba de dh’àidseantan a’ dèanamh nan cairtean agus thusa a’ dèanamh nan co-dhùnaidhean. Pasgaidh e cairtean co-cheangailte còmhla, ceartaichidh e tiotalan measgaichte, agus cumaidh e sùil air cho caol ’s a dh’fhanas an còd. Bruidhnidh e mu 120 cànan, bhon Duitsis agus Flemis gu spùinneadair agus Klingon. Faodaidh caraidean teachdaireachdan a chur gu chèile, gu prìobhaideach agus crioptaichte. Chaidh a thogail le Rich agus mòran àidseantan foighidneach, a’ cleachdadh fhèin sa mhòr-chuid. Tha e ann am ro-alpha dùinte, mar sin tha e garbh an siud ’s an seo. Ma tha e coltach le spòrs, iarr gu modhail agus is dòcha gum faigh thu a-steach tràth."]}],"quips":{"1":"Aon fhacal. Dàna. Is dòcha ro dhàna.","3":"Trì faclan. Nas onaraich na a’ mhòr-chuid de dhuilleagan toraidh mar-thà.","8":"Ochd faclan. Fhathast nas giorra na stand-up.","21":"Is e puingean sgeòil a th’ anns na faid, co-dhiù. Gu dearbh is e.","55":"Còig fichead ’s a còig faclan. Chaidh dà chairt a chrìochnachadh fhad ’s a leugh thu sin.","144":"Sin am fear fada. Chan eil 233 ann. Tha na h-àidseantan air a dhol dhan leabaidh."}},"timeline":{"first-idea.name":"A’ chiad bheachd","first-idea.line":"A’ chiad chòmhradh, mus robh còd sam bith ann.","first-board.name":"A’ chiad bhòrd","first-board.line":"Bòrd a bhios a’ cumail sùil air a thogail fhèin: cairtean, colbhan, slaodadh is leigeil às, pròiseactan.","team-roles.name":"Sgioba is dreuchdan","team-roles.line":"Pròifilean àidseant, teamplaidean sgioba, àiteachan agus cò a nì dè.","install.name":"Stàlaich is sgaoilidhean","install.line":"Zip a stàlaicheas caraid, fèin-ùrachadh, seanailean agus tilleadh air ais.","usage-saver.name":"Sàbhaladh cleachdaidh","usage-saver.line":"Tomhais cosgais ruith, cùm an còd caol, sàbhail do chrìoch.","friends.name":"Caraidean is co-roinn","friends.line":"DMan prìobhaideach, ceangal measgaichte, cuiridhean, dreuchdan is pròiseactan co-roinnte.","languages.name":"Cànanan","languages.line":"Gach teacsa sgrìn ann am faidhle cànain, leis an Duitsis is Flemis an toiseach.","ai-tester.name":"Deuchainniche AI","ai-tester.line":"Bidh deuchainniche a’ sgrùdadh gach lìbhrigidh an toiseach agus a’ sealltainn na chunnaic e.","website.name":"An làrach-lìn","website.line":"aigile.lol, an teaser agus an loidhne-ama seo.","streaming.name":"Cabadaich is sruthadh","streaming.line":"Discord, Twitch, OBS, modh sruthadair, GIFs agus emojis.","no-ai.name":"Deasachadh gun AI","no-ai.line":"Bòrd airson daoine a chòdaicheas gun AI, agus bùird phoblach.","night-watch.name":"Faire na h-oidhche","night-watch.line":"Bidh fear-faire agus Scrum Master a’ cumail nan sgiobaidhean air an obair fhad ’s a tha thu nad chadal.","p-more.name":"A h-uile rud eile","p-more.line":"Beachdan nas lugha a tha fhathast a’ feitheamh an cothrom.","p-android.name":"Fòn is Android","p-android.line":"Ruig do bhòrd o fòn, an uairsin aplacaid Android dhùthchasach.","p-release.name":"Alpha is nas fhaide","p-release.line":"Alpha dùinte, an làrach bheò, an uairsin beta.","p-languages.name":"Barrachd chànanan","p-languages.line":"Còrr is ceud cànan, agus modh bogaidh airson luchd-ionnsachaidh.","p-engines.name":"Barrachd einnseanan AI","p-engines.line":"Tagh Claude, Codex no Gemini airson gach àidseant.","p-pro.name":"Cleachdadh proifeasanta","p-pro.line":"Leubailean cunnairt, geataichean cothlamaidh, cairtean thachartasan agus rèilichean-dìon.","p-self.name":"A’ coimhead às do dhèidh","p-self.line":"Modh claoidhte, cuimhneachain fèin-chùraim agus 4:20.","p-servers.name":"Frithealaichean is sgèile","p-servers.line":"Roghainnean frithealaiche cruinneil, dreuchdan agus dealbhadh airson fàs.","p-livestream.name":"Rudan a bharrachd airson sruthadh","p-livestream.line":"Cabadaich Twitch, emojis gnàthaichte agus sealladh beò poblach."}};
